namespace sv_cd64e6a064de4c3c8d4186a07a0629ed.Models;

public sealed class Recipe
{
    public required int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public required int PrepTimeMinutes { get; init; }
}

using sv_cd64e6a064de4c3c8d4186a07a0629ed.Models;

namespace sv_cd64e6a064de4c3c8d4186a07a0629ed.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> CuisineRecipes = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic Italian pizza with tomato, mozzarella, and basil.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Pasta Carbonara", Description = "Creamy pasta with pancetta, egg yolk, and Pecorino Romano.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-flavored dessert with mascarpone cream.", PrepTimeMinutes = 45 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Chicken Tikka Masala", Description = "Tender chicken in a spiced tomato and cream sauce.", PrepTimeMinutes = 50 },
            new() { Id = 5, Title = "Palak Paneer", Description = "Spinach curry with cubes of soft paneer cheese.", PrepTimeMinutes = 35 },
            new() { Id = 6, Title = "Biryani", Description = "Fragrant basmati rice layered with spiced meat and saffron.", PrepTimeMinutes = 60 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Sushi Rolls", Description = "Vinegared rice with fresh fish and vegetables wrapped in nori.", PrepTimeMinutes = 40 },
            new() { Id = 8, Title = "Ramen", Description = "Rich pork broth with noodles, chashu, and a soft-boiled egg.", PrepTimeMinutes = 55 },
            new() { Id = 9, Title = "Tempura", Description = "Lightly battered and deep-fried shrimp and vegetables.", PrepTimeMinutes = 20 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (CuisineRecipes.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_cd64e6a064de4c3c8d4186a07a0629ed.Models
@using sv_cd64e6a064de4c3c8d4186a07a0629ed.Services
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h3>Recipes for Cuisine @CuisineId</h3>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex justify-content-between align-items-center" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _isLoading)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border spinner-border-sm" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else if (_recipes is not null)
{
    @if (_isLoading)
    {
        <div class="d-flex align-items-center gap-2 mb-3">
            <div class="spinner-border spinner-border-sm" role="status"></div>
            <small class="text-muted">Refreshing…</small>
        </div>
    }

    <div class="row">
        @foreach (var recipe in DisplayedRecipes)
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <span class="badge bg-secondary">@recipe.PrepTimeMinutes min prep</span>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isLoading;
    private string? _errorMessage;
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    private IReadOnlyList<Recipe> DisplayedRecipes
    {
        get
        {
            if (_recipes is null) return Array.Empty<Recipe>();
            return string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
                ? _recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
                : _recipes.OrderByDescending(r => r.Id).ToList();
        }
    }

    protected override Task OnParametersSetAsync()
    {
        if (CuisineId != _loadedCuisineId)
        {
            return LoadRecipesAsync();
        }

        return Task.CompletedTask;
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        await CancelPendingRequestAsync();

        _cts = new CancellationTokenSource();
        var cancellationToken = _cts.Token;

        _loadedCuisineId = CuisineId;
        _errorMessage = null;
        _isLoading = true;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(CuisineId, cancellationToken);
            cancellationToken.ThrowIfCancellationRequested();
            _recipes = results;
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            // Request was superseded or component is disposing; do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task RetryAsync()
    {
        _errorMessage = null;
        _loadedCuisineId = 0; // force reload
        await LoadRecipesAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

